function xpNeed(l){return Math.floor(80*Math.pow(l,1.55))}function combatLevel(){let sk=save.skills,melee=(sk.Attack.lvl+sk.Strength.lvl)/2,style=Math.max(melee,sk.Ranged.lvl,sk.Magic.lvl);return Math.max(3,Math.floor((sk.Defence.lvl+sk.Hitpoints.lvl)*.25+style*.325))}function totalDefence(){return ['warrior','ranger','mage'].reduce((n,c)=>n+bonus(c,'defence'),0)}function addXP(skill,n){let s=save.skills[skill];s.xp+=n;while(s.lvl<99&&s.xp>=xpNeed(s.lvl)){s.xp-=xpNeed(s.lvl);s.lvl++}writeSave(false)}function persist(){writeSave(true);renderUI()}function bonus(cls,key){return Object.values(save.equipment[cls]).reduce((n,name)=>n+(itemDB[name]?.[key]||0),0)}
