let cookingKey=null,cookingTimer=null,cookingStart=0;
function startCooking(key){var r=cookDB[key];if(!r)return;if(save.skills.Cooking.lvl<r.level){msg('You need Cooking level '+r.level+'.');return}if((save.bank[r.raw]||0)<1){msg('You need '+r.raw+'.');return}stopCooking(false);stopGathering(false);cookingKey=key;cookingStart=performance.now();var an=document.querySelector('#activityName'),at=document.querySelector('#activityText'),sb=document.querySelector('#stopGather');if(an)an.textContent='Cooking '+r.cooked;if(at)at.textContent='Cooking automatically until you run out...';if(sb)sb.disabled=false;cookingTimer=setInterval(function(){completeCooking(key)},r.time);renderCookingProgress()}
function completeCooking(key){if(cookingKey!==key)return;var r=cookDB[key];if((save.bank[r.raw]||0)<1){msg('Cooking stopped: you ran out of '+r.raw+'.');stopCooking();renderUI();return}save.bank[r.raw]--;var chance=Math.max(.02,r.burn-save.skills.Cooking.lvl*.004);if(Math.random()<chance){addXP('Cooking',Math.ceil(r.xp*.25));msg('The fish burns.')}else{save.bank[r.cooked]=(save.bank[r.cooked]||0)+1;addXP('Cooking',r.xp);msg('You cook 1 '+r.cooked+'.')}cookingStart=performance.now();renderUI()}
