let gathering=null,gatherStart=0,gatherTimer=null;
function startGathering(type){let g=gatherDB[type];if(!g)return;if(save.skills[g.skill].lvl<g.level){msg('You need '+g.skill+' level '+g.level+'.');return}if(type==='bronze'&&(save.bank['Copper ore']<1||save.bank['Tin ore']<1)){msg('You need Copper and Tin ore to start smelting.');return}if(type==='frostbar'&&save.bank['Frostsilver ore']<2){msg('You need 2 Frostsilver ore to start smelting.');return}if(type==='ironbar'&&save.bank['Ironvale ore']<2){msg('You need 2 Ironvale ore to start smelting.');return}stopGathering(false);gathering=type;gatherStart=performance.now();activityName.textContent=g.verb;activityText.textContent='Gathering automatically...';stopGather.disabled=false;gatherTimer=setInterval(()=>completeGather(type),g.time);renderGatherProgress()}
function completeGather(type){if(gathering!==type)return;let g=gatherDB[type];if(type==='bronze'){if(save.bank['Copper ore']<1||save.bank['Tin ore']<1){msg('Smelting stopped: you ran out of Copper or Tin ore.');stopGathering();renderUI();return}save.bank['Copper ore']--;save.bank['Tin ore']--;save.bank['Bronze bar']++;addXP('Smithing',12);gatherStart=performance.now();msg('You smelt 1 Bronze bar.');renderUI();return}if(type==='frostbar'){if(save.bank['Frostsilver ore']<2){msg('Smelting stopped: you need 2 Frostsilver ore.');stopGathering();renderUI();return}save.bank['Frostsilver ore']-=2;save.bank['Frostsilver bar']++;addXP('Smithing',65);gatherStart=performance.now();msg('You smelt 1 Frostsilver bar.');renderUI();return}if(type==='ironbar'){if(save.bank['Ironvale ore']<2){msg('Smelting stopped: you need 2 Ironvale ore.');stopGathering();renderUI();return}save.bank['Ironvale ore']-=2;save.bank['Ironvale bar']++;addXP('Smithing',30);gatherStart=performance.now();msg('You smelt 1 Ironvale bar.');renderUI();return}save.bank[g.item]=(save.bank[g.item]||0)+1;addXP(g.skill,g.xp);gatherStart=performance.now();msg('You gather 1 '+g.item+'.');renderUI()}
function stopGathering(show=true){if(gatherTimer)clearInterval(gatherTimer);gatherTimer=null;gathering=null;if(window.activityName)activityName.textContent='Not currently gathering';if(window.activityText)activityText.textContent=show?'Gathering stopped.':'Choose a resource below.';if(window.stopGather)stopGather.disabled=true;if(window.activityProgress)activityProgress.querySelector('i').style.width='0%'}
function renderGatherProgress(){if(!gathering)return;let g=gatherDB[gathering],pct=Math.min(100,(performance.now()-gatherStart)/g.time*100);if(window.activityProgress)activityProgress.querySelector('i').style.width=pct+'%';requestAnimationFrame(renderGatherProgress)}
window.startGathering=startGathering;window.stopGathering=stopGathering;
let smithingKey=null,smithTimer=null,smithStart=0;
function startSmithing(key){let r=recipes[key];if(!r)return;if(save.skills.Smithing.lvl<r.level){msg('You need Smithing level '+r.level+'.');return}if((save.bank[r.resource]||0)<r.bars){msg('You need '+r.bars+' '+r.resource+(r.bars>1?'s':'')+'.');return}stopGathering(false);stopSmithing(false);smithingKey=key;smithStart=performance.now();activityName.textContent='Smithing '+r.name;activityText.textContent='Producing automatically...';stopGather.disabled=false;smithTimer=setInterval(()=>completeSmithing(key),r.time);renderSmithProgress()}
function completeSmithing(key){if(smithingKey!==key)return;let r=recipes[key];if((save.bank[r.resource]||0)<r.bars){msg('Smithing stopped: not enough '+r.resource+'.');stopSmithing();renderUI();return}save.bank[r.resource]-=r.bars;save.items[r.name]=(save.items[r.name]||0)+1;questCraft(r.name);addXP('Smithing',r.xp);smithStart=performance.now();msg('You smith 1 '+r.name+'.');renderUI()}
function stopSmithing(show=true){if(smithTimer)clearInterval(smithTimer);smithTimer=null;smithingKey=null;if(show&&window.activityName){activityName.textContent='Not currently gathering';activityText.textContent='Smithing stopped.';stopGather.disabled=true;activityProgress.querySelector('i').style.width='0%'}}
function renderSmithProgress(){if(!smithingKey)return;let r=recipes[smithingKey],pct=Math.min(100,(performance.now()-smithStart)/r.time*100);activityProgress.querySelector('i').style.width=pct+'%';requestAnimationFrame(renderSmithProgress)}
const oldStopGather=stopGathering;stopGathering=function(show=true){oldStopGather(show);if(smithingKey)stopSmithing(show)}
window.startSmithing=startSmithing;
function equipItem(name){let it=itemDB[name];if(!it||!(save.items[name]>0))return;if(it.req){for(const [skill,lvl] of Object.entries(it.req))if(save.skills[skill].lvl<lvl){alert(name+' requires '+skill+' level '+lvl+'.');return}}save.equipment[it.class][it.slot]=name;persist()}window.equipItem=equipItem;


