{id:'frostcall',name:'The Frozen Warning',npc:'Ranger Sera',story:'Scouts returning from Frostmere speak of creatures moving beneath the snow and a shadow circling the Citadel of Ice.',req:()=>save.quests.completed.includes('tyrant')&&save.campaign.unlocked>=11,objective:'Defeat 15 Frost Wolves and 12 Ice Raiders',done:()=>qkill('frostwolf')>=15&&qkill('iceraider')>=12,reward:'2,000 coins + 8 Frostsilver ore + 5 Frostpine logs',give:()=>{save.coins+=2000;save.bank['Frostsilver ore']+=8;save.bank['Frostpine logs']+=5}},
{id:'frostforge',name:'Forged for the North',npc:'Smith Torren',story:'Ordinary metal cracks in Frostmere. Torren wants you to prove Frostsilver can be shaped into equipment worthy of the northern campaign.',req:()=>save.quests.completed.includes('frostcall')&&save.skills.Smithing.lvl>=28,objective:'Smith a Frostsilver Helm and Frostsilver Sword',done:()=>qcraft('Frostsilver Helm')>=1&&qcraft('Frostsilver Sword')>=1,reward:'3,000 coins + 6 Frostsilver bars',give:()=>{save.coins+=3000;save.bank['Frostsilver bar']+=6}},
{id:'wyrm',name:'Crown of Winter',npc:'Warden Elira',story:'The Frost Wyrm has awakened above the Citadel of Ice. Elira calls every surviving ally to end the threat before Frostmere is buried beneath an endless winter.',req:()=>save.quests.completed.includes('frostcall')&&save.campaign.unlocked>=15,objective:'Defeat the Frost Wyrm',done:()=>save.campaign.frostBossKills>=1,reward:'5,000 coins + Frostbound Cape + 40 Hunter Points',give:()=>{save.coins+=5000;save.items['Frostbound Cape']=(save.items['Frostbound Cape']||0)+1;save.hunter.points+=40}}
