function qkill(k){return Number(save.quests.kills[k])||0}function qcraft(k){return Number(save.quests.crafted[k])||0}
function questKill(k){save.quests.kills[k]=qkill(k)+1}
function questCraft(n){save.quests.crafted[n]=qcraft(n)+1}
function startQuest(id){let q=questDB.find(x=>x.id===id);if(!q||!q.req()||save.quests.started.includes(id)||save.quests.completed.includes(id))return;save.quests.started.push(id);persist()}window.startQuest=startQuest;
function claimQuest(id){let q=questDB.find(x=>x.id===id);if(!q||!save.quests.started.includes(id)||!q.done()||save.quests.completed.includes(id))return;q.give();save.quests.completed.push(id);save.drops.push('QUEST COMPLETE: '+q.name);persist();alert('Quest complete: '+q.name+'\nReward: '+q.reward)}window.claimQuest=claimQuest;
function renderQuests(){let g=document.querySelector('#questGrid'),st=document.querySelector('#questStats');if(!g)return;st.textContent=save.quests.completed.length+' / '+questDB.length+' quests completed';g.innerHTML=questDB.map(q=>{let complete=save.quests.completed.includes(q.id),started=save.quests.started.includes(q.id),available=q.req(),ready=started&&q.done();return '<div class="questCard '+(complete?'questComplete':!available?'questLocked':'')+'"><span class="questNpc">'+q.npc+'</span><h3>'+q.name+'</h3><p>'+q.story+'</p><b>Objective</b><p>'+q.objective+'</p><small>Reward: '+q.reward+'</small><div class="questAction">'+(complete?'<strong>QUEST COMPLETE</strong>':!available?'<button disabled>Requirements not met</button>':!started?'<button onclick="startQuest(\''+q.id+'\')">Start Quest</button>':ready?'<button onclick="claimQuest(\''+q.id+'\')">Claim Reward</button>':'<strong>IN PROGRESS</strong>')+'</div></div>'}).join('')}


